module longest_non_decreasing_subsequence(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] n,\n    input [7:0] T,\n    input [7:0] base_array_0,\n    input [7:0] base_array_1,\n    input [7:0] base_array_2,\n    input [7:0] base_array_3,\n    input [7:0] base_array_4,\n    input [7:0] base_array_5,\n    input [7:0] base_array_6,\n    input [7:0] base_array_7,\n    output reg [15:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE     = 3'd0;\n    localparam [2:0] EXPAND   = 3'd1;\n    localparam [2:0] INIT_DP  = 3'd2;\n    localparam [2:0] DP_OUTER = 3'd3;\n    localparam [2:0] DP_INNER = 3'd4;\n    localparam [2:0] FIND_MAX = 3'd5;\n    localparam [2:0] COMPLETE = 3'd6;\n\n    // Internal registers\n    reg [2:0] state;\n    reg [7:0] arr [0:63];  // Expanded array (max 64 elements)\n    reg [7:0] dp [0:63];   // DP table\n    reg [7:0] L;\n    reg [7:0] rep;\n    reg [7:0] base_idx;\n    reg [7:0] base_addr;\n    reg [7:0] i_index;\n    reg [7:0] j_index;\n    reg [7:0] max_val;\n    reg [7:0] cycle_counter;\n\n    // Base array multiplexer\n    wire [7:0] base_val;\n    assign base_val = (base_idx == 3'd0) ? base_array_0 :\n                     (base_idx == 3'd1) ? base_array_1 :\n                     (base_idx == 3'd2) ? base_array_2 :\n                     (base_idx == 3'd3) ? base_array_3 :\n                     (base_idx == 3'd4) ? base_array_4 :\n                     (base_idx == 3'd5) ? base_array_5 :\n                     (base_idx == 3'd6) ? base_array_6 :\n                     base_array_7;\n\n    integer k;  // For-loop index\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 16'd0;\n            L <= 8'd0;\n            rep <= 8'd0;\n            base_idx <= 8'd0;\n            base_addr <= 8'd0;\n            i_index <= 8'd0;\n            j_index <= 8'd0;\n            max_val <= 8'd0;\n            cycle_counter <= 8'd0;\n\n            // Initialize arrays\n            for (k = 0; k < 64; k = k + 1) begin\n                arr[k] <= 8'd0;\n                dp[k] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_counter <= 8'd0;\n                    if (start) begin\n                        L <= n * T;\n                        rep <= 8'd0;\n                        base_idx <= 8'd0;\n                        base_addr <= 8'd0;\n                        state <= EXPAND;\n                    end\n                end\n\n                EXPAND: begin\n                    cycle_counter <= cycle_counter + 8'd1;\n                    if (rep < T) begin\n                        if (base_idx < n) begin\n                            arr[base_addr + base_idx] <= base_val;\n                            base_idx <= base_idx + 8'd1;\n                        end else begin\n                            rep <= rep + 8'd1;\n                            base_idx <= 8'd0;\n                            base_addr <= base_addr + n;\n                        end\n                    end else begin\n                        state <= INIT_DP;\n                        i_index <= 8'd0;\n                    end\n\n                    // Prevent infinite loops (100 cycles max)\n                    if (cycle_counter > 8'd100) state <= IDLE;\n                end\n\n                INIT_DP: begin\n                    if (i_index < L) begin\n                        dp[i_index] <= 8'd1;\n                        i_index <= i_index + 8'd1;\n                    end else begin\n                        state <= DP_OUTER;\n                        i_index <= 8'd0;\n                    end\n                end\n\n                DP_OUTER: begin\n                    if (i_index < L) begin\n                        state <= DP_INNER;\n                        j_index <= 8'd0;\n                    end else begin\n                        state <= FIND_MAX;\n                        i_index <= 8'd0;\n                        max_val <= dp[0];\n                    end\n                end\n\n                DP_INNER: begin\n                    if (j_index < i_index) begin\n                        if (arr[j_index] <= arr[i_index]) begin\n                            if (dp[j_index] + 8'd1 > dp[i_index]) begin\n                                dp[i_index] <= dp[j_index] + 8'd1;\n                            end\n                        end\n                        j_index <= j_index + 8'd1;\n                    end else begin\n                        state <= DP_OUTER;\n                        i_index <= i_index + 8'd1;\n                    end\n                end\n\n                FIND_MAX: begin\n                    if (i_index < L) begin\n                        if (dp[i_index] > max_val) begin\n                            max_val <= dp[i_index];\n                        end\n                        i_index <= i_index + 8'd1;\n                    end else begin\n                        state <= COMPLETE;\n                    end\n                end\n\n                COMPLETE: begin\n                    result <= {8'd0, max_val};\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule